// MergeToolAuthorization fills zero-valued fields in dst from src.
func MergeToolAuthorization(dst, src *ToolAuthorization) {
	if dst.Service == "" {
		dst.Service = src.Service
	}
	if len(dst.Methods) == 0 {
		dst.Methods = src.Methods
	}
}

// ============================================================
// Merge: AgentToken
// ============================================================
// MergeAgentToken fills zero-valued fields in dst from src.
func MergeAgentToken(dst, src *AgentToken) {
	if dst.Service == "" {
		dst.Service = src.Service
	}
	if dst.Token == "" {
		dst.Token = src.Token
	}
}

// ============================================================
// Merge: AssistToolRequest
// ============================================================
// MergeAssistToolRequest fills zero-valued fields in dst from src.
func MergeAssistToolRequest(dst, src *AssistToolRequest) {
	if len(dst.RequestedTools) == 0 {
		dst.RequestedTools = src.RequestedTools
	}
	if dst.Justification == "" {
		dst.Justification = src.Justification
	}
}

// ============================================================
// Merge: AssistRequest
// ============================================================
// MergeAssistRequest fills zero-valued fields in dst from src.
func MergeAssistRequest(dst, src *AssistRequest) {
	if dst.SessionId == "" {
		dst.SessionId = src.SessionId
	}
	if dst.Prompt == "" {
		dst.Prompt = src.Prompt
	}
	if len(dst.AuthorizedTools) == 0 {
		dst.AuthorizedTools = src.AuthorizedTools
	}
	if len(dst.AgentTokens) == 0 {
		dst.AgentTokens = src.AgentTokens
	}
}

// ============================================================
// Merge: AssistResponse
// ============================================================
// MergeAssistResponse fills zero-valued fields in dst from src.
func MergeAssistResponse(dst, src *AssistResponse) {
	if dst.SessionId == "" {
		dst.SessionId = src.SessionId
	}
	if dst.ResponseType == 0 {
		dst.ResponseType = src.ResponseType
	}
	if dst.ToolRequest == nil {
		dst.ToolRequest = src.ToolRequest
	} else if src.ToolRequest != nil {
		MergeAssistToolRequest(dst.ToolRequest, src.ToolRequest)
	}
	if dst.Result == nil {
		dst.Result = src.Result
	}
}
